<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:12.5px;margin-bottom:2px">Natural draft cooling tower</div>
<div style="color:#555;line-height:1.35;margin-bottom:4px">
  Surface of revolution of the hyperbola<br>
  <span style="font-family:ui-monospace,Consolas,monospace">x²/30² − y²/120² = 1</span><br>
  (a = 30 m waist radius, b = 120 m)
</div>

<label style="margin-top:4px">Measurement height above ground: <span id="mhOut">100.0</span> m
  <input type="range" id="measureHeight" min="0" max="179.6" step="0.4" value="100">
</label>
<div id="diamOut" style="color:#1B6CA8;font-weight:700">diameter = 60.0 m</div>
<div style="color:#666;line-height:1.3">Minimum span (60 m) occurs exactly at the waist, 100 m above ground.</div>

<div style="margin-top:6px;font-weight:600">View</div>
<div style="display:flex;gap:4px;flex-wrap:wrap">
