const C_TEAL = 0x5FA8A3, C_TEALD = 0x3E8481, C_DIM = 0x333333, C_MEAS = 0x1B6CA8;

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xe8e8e8, 1.0));
const dl = new THREE.DirectionalLight(0xffffff, 0.55);
dl.position.set(3, 4, 2);
scene.add(dl);

/* ── small builders ─────────────────────────────────────────────────────── */
function lineFrom(pts, color, opts = {}) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = opts.dashed
    ? new THREE.LineDashedMaterial({
        color, dashSize: opts.dashSize ?? 0.055, gapSize: opts.gapSize ?? 0.035,
        transparent: true, opacity: opts.opacity ?? 1
      })
    : new THREE.LineBasicMaterial({ color, transparent: true, opacity: opts.opacity ?? 1 });
  const l = new THREE.Line(g, m);
  if (opts.dashed) l.computeLineDistances();
  return l;
}
const ARROW_L = 0.115, ARROW_R = 0.038;
function makeCone(color) {
  const g = new THREE.ConeGeometry(ARROW_R, ARROW_L, 14);
  return new THREE.Mesh(g, new THREE.MeshBasicMaterial({ color, transparent: true }));
}
const _up = new THREE.Vector3(0, 1, 0);
function placeCone(mesh, tip, dir) {
  mesh.quaternion.setFromUnitVectors(_up, dir);
  mesh.position.copy(tip).addScaledVector(dir, -ARROW_L / 2);
}
function dimArrow(u1, v1, u2, v2, color) {
  const g = new THREE.Group();
  const p1 = P(u1, v1), p2 = P(u2, v2);
  g.add(lineFrom([p1, p2], color));
  const dir = p2.clone().sub(p1).normalize();
  const c2 = makeCone(color), c1 = makeCone(color);
  placeCone(c2, p2, dir); placeCone(c1, p1, dir.clone().negate());
  g.add(c1); g.add(c2);
  return g;
}
function tick(u1, v1, u2, v2, color) { return lineFrom([P(u1, v1), P(u2, v2)], color); }
function circleLoop(radiusW, yW, color, opacity = 1, segs = 96) {
  const pts = [];
  for (let i = 0; i <= segs; i++) {
    const a = i / segs * Math.PI * 2;
    pts.push(new THREE.Vector3(Math.cos(a) * radiusW, yW, Math.sin(a) * radiusW));
  }
  return lineFrom(pts, color, { opacity });
}

/* ── profile samples ────────────────────────────────────────────────────── */
const NP = 120;
const profile2 = [], profileY = [];
for (let i = 0; i < NP; i++) {
  const y = Y_GND + (Y_TOP - Y_GND) * i / (NP - 1);
  profileY.push(y);
  profile2.push(new THREE.Vector2(rOf(y) * S, y * S));
}

/* ── 1. shell (lathe) ───────────────────────────────────────────────────── */
const grpSolid = new THREE.Group(); scene.add(grpSolid);
const shellMat = new THREE.MeshPhysicalMaterial({
  color: C_FILL, transparent: true, opacity: 0.45, side: THREE.DoubleSide,
  depthWrite: false, roughness: 0.75, metalness: 0.0, clearcoat: 0.2
});
const shell = new THREE.Mesh(new THREE.LatheGeometry(profile2, 96), shellMat);
grpSolid.add(shell);

/* ── 2. meridian contours on the near-LEFT quarter ──────────────────────── */
const grpContours = new THREE.Group(); scene.add(grpContours);
{
  const segPts = [];
  const NM = 18, NS = 70;
  for (let k = 0; k < NM; k++) {
    const phi = THREE.MathUtils.degToRad(3 + 87 * k / (NM - 1)); // 3°..90°: x>0 (near), z>0 (screen-left)
    const cx = Math.cos(phi), cz = Math.sin(phi);
    let prev = null;
    for (let i = 0; i < NS; i++) {
      const y = Y_GND + (Y_TOP - Y_GND) * i / (NS - 1);
      const r = rOf(y) * S;
      const p = new THREE.Vector3(cx * r, y * S, cz * r);
      if (prev) { segPts.push(prev, p); }
      prev = p;
    }
  }
  const g = new THREE.BufferGeometry().setFromPoints(segPts);
  const m = new THREE.LineBasicMaterial({ color: C_MER, transparent: true, opacity: 0.7 });
  grpContours.add(new THREE.LineSegments(g, m));
}

/* ── 3. rings (top rim, base rim, waist) + measurement circle ───────────── */
const grpRings = new THREE.Group(); scene.add(grpRings);
const R_BASE = rOf(Y_GND);
grpRings.add(circleLoop(rOf(Y_TOP) * S, Y_TOP * S, C_EDGE, 1));   // 72 m top rim
grpRings.add(circleLoop(R_BASE * S, Y_GND * S, C_EDGE, 0.9));     // base rim
grpRings.add(circleLoop(A_HYP * S, 0, C_EDGE, 0.55));             // 60 m waist ring
const measCircle = circleLoop(1, 0, C_MEAS, 0.75);
grpRings.add(measCircle);

/* ── 4. teal splayed supports around the open base ──────────────────────── */
const grpLegs = new THREE.Group(); scene.add(grpLegs);
{
  const legGeo = new THREE.BoxGeometry(2 * S, 8 * S, 1.2 * S);
  const legMat = new THREE.MeshPhysicalMaterial({ color: C_TEAL, transparent: true, opacity: 1, roughness: 0.8 });
  const edgeGeo = new THREE.EdgesGeometry(legGeo);
  const edgeMat = new THREE.LineBasicMaterial({ color: C_TEALD, transparent: true, opacity: 1 });
  const NL = 18;
  for (let i = 0; i < NL; i++) {
    const a = i / NL * Math.PI * 2;
    const pivot = new THREE.Group();
    pivot.rotation.y = -a;                       // local +X points radially outward
    const leg = new THREE.Mesh(legGeo, legMat);
    leg.position.set((R_BASE + 1.4) * S, (Y_GND + 4) * S, 0);
    leg.rotation.z = 0.35;                       // ~20° lean, top toward the axis
    const outline = new THREE.LineSegments(edgeGeo, edgeMat);
    outline.position.copy(leg.position); outline.rotation.z = leg.rotation.z;
    pivot.add(leg); pivot.add(outline);
    grpLegs.add(pivot);
  }
}

/* ── 5. flat (always visible) figure elements ───────────────────────────── */
const grpFlat = new THREE.Group(); scene.add(grpFlat);

// silhouette / profile branches
const branchPts = { L: [], R: [] };
for (const y of profileY) {
  branchPts.L.push(P(-rOf(y), y));
  branchPts.R.push(P(rOf(y), y));
}
grpFlat.add(lineFrom(branchPts.L, C_EDGE));
grpFlat.add(lineFrom(branchPts.R, C_EDGE));

// ground line
grpFlat.add(lineFrom([P(-118, Y_GND), P(52, Y_GND)], C_EDGE, { opacity: 0.85 }));

// dashed axis of revolution + dashed waist chord
grpFlat.add(lineFrom([P(0, Y_GND), P(0, Y_TOP + 4)], C_EDGE, { dashed: true, opacity: 0.95 }));
grpFlat.add(lineFrom([P(-32, 0), P(32, 0)], C_EDGE, { dashed: true, opacity: 0.95 }));

// dimension: 72 m across the top rim
grpFlat.add(dimArrow(-36, Y_TOP + 22, 36, Y_TOP + 22, C_DIM));
grpFlat.add(tick(-36, Y_TOP + 3, -36, Y_TOP + 28, C_DIM));
grpFlat.add(tick(36, Y_TOP + 3, 36, Y_TOP + 28, C_DIM));
// dimension: 60 m across the waist
grpFlat.add(dimArrow(-30, 0, 30, 0, C_DIM));
// dimension: 79.6 m (top rim down to waist), just left of the tower
grpFlat.add(dimArrow(-45, Y_TOP, -45, 0, C_DIM));
grpFlat.add(tick(-52, Y_TOP, -38, Y_TOP, C_DIM));
grpFlat.add(tick(-52, 0, -38, 0, C_DIM));
// dimension: 179.6 m full height, far left
grpFlat.add(dimArrow(-110, Y_TOP, -110, Y_GND, C_DIM));
grpFlat.add(tick(-117, Y_TOP, -103, Y_TOP, C_DIM));
grpFlat.add(tick(-117, Y_GND, -103, Y_GND, C_DIM));

// measuring chord (interactive)
const chordPos = new Float32Array(6);
const chordGeo = new THREE.BufferGeometry();
chordGeo.setAttribute('position', new THREE.BufferAttribute(chordPos, 3));
const chordLine = new THREE.Line(chordGeo, new THREE.LineBasicMaterial({ color: C_MEAS }));
const chordC1 = makeCone(C_MEAS), chordC2 = makeCone(C_MEAS);
grpFlat.add(chordLine); grpFlat.add(chordC1); grpFlat.add(chordC2);

/* ── 6. hyperbola-profile extras (fade in with the toggle) ──────────────── */
const grpProfile = new THREE.Group(); grpProfile.visible = false; scene.add(grpProfile);
{
  // bold copies of both branches (slight depth offsets fake a thick stroke head-on)
  for (const off of [-0.006, 0.006]) {
    for (const key of ['L', 'R']) {
      const pts = branchPts[key].map(p => new THREE.Vector3(p.x + off, p.y, p.z));
      grpProfile.add(lineFrom(pts, C_EDGE));
    }
  }
  // asymptotes v = ±(b/a) u = ±4u
  const U = 26;
  grpProfile.add(lineFrom([P(-U, 4 * U), P(U, -4 * U)], 0x999999, { dashed: true, dashSize: 0.05, gapSize: 0.045 }));
  grpProfile.add(lineFrom([P(-U, -4 * U), P(U, 4 * U)], 0x999999, { dashed: true, dashSize: 0.05, gapSize: 0.045 }));
  // centre point of the hyperbola
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.035, 16, 12),
    new THREE.MeshBasicMaterial({ color: C_EDGE, transparent: true }));
  dot.position.copy(P(0, 0));
  grpProfile.add(dot);
}

/* ── camera (after all geometry) ────────────────────────────────────────── */
function applyCamera(profile) {
  setCameraView({
    projection: 'perspective',
    azimuthDeg: 0,
    elevationDeg: profile ? 0 : 4,
    rollDeg: 0,
    heightFraction: 0.72
  });
}
applyCamera(false);
document.getElementById('btnReset').style.display = '';

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('72 m', P(0, Y_TOP + 34), { color: '#333', fontSize: '13px' });
addLabel('60 m', P(0, 0), { color: '#333', fontSize: '13px', offset: [0, -13], background: '#fff' });
addLabel('79.6 m', P(-47, 40), { color: '#333', fontSize: '13px', offset: [-32, 0] });
addLabel('179.6 m', P(-112, -10), { color: '#333', fontSize: '13px', offset: [-40, 0] });
const measLabel = addLabel('60.0 m', P(0, 0), { color: '#1B6CA8', fontSize: '13px', bold: true, offset: [0, 15] });
const eqLabel = addLabel('x²/30² &minus; y²/120² = 1', P(66, 56), { color: '#E07B43', fontSize: '13px', bold: true });
eqLabel.div.style.opacity = '0';
const ctrLabel = addLabel('centre', P(0, 0), { color: '#E07B43', fontSize: '11px', offset: [-30, 13] });
ctrLabel.div.style.opacity = '0';

/* ── interactivity: hover / click explanations ──────────────────────────── */
registerInteractive(shell, {
  title: 'Hyperboloid shell',
  tooltip: 'The shell is a surface of revolution',
  body: 'Rotating the hyperbola x²/30² − y²/120² = 1 about the vertical axis gives the tower. ' +
        'At height y above the waist the radius is r(y) = 30·√(1 + y²/120²), so r(0) = 30 m (60 m waist) ' +
        'and r(79.6) = 36 m (72 m top rim).'
});
registerInteractive(grpLegs, {
  title: 'Base supports',
  tooltip: 'Splayed legs at the open base',
  body: 'The ring of angled legs holds the shell above the ground so air can be drawn in all round the base.'
});

/* ── measurement chord update ───────────────────────────────────────────── */
const slider = document.getElementById('measureHeight');
const mhOut = document.getElementById('mhOut');
const diamOut = document.getElementById('diamOut');
const DIR_R = new THREE.Vector3(0, 0, -1), DIR_L = new THREE.Vector3(0, 0, 1);

function updateMeasure() {
  const h = parseFloat(slider.value);
  const v = h - 100;
  const r = rOf(v);
  const diam = 2 * r;
  mhOut.textContent = h.toFixed(1);
  diamOut.textContent = 'diameter = ' + diam.toFixed(1) + ' m';

  const pL = P(-r, v), pR = P(r, v);
  chordPos[0] = pL.x; chordPos[1] = pL.y; chordPos[2] = pL.z;
  chordPos[3] = pR.x; chordPos[4] = pR.y; chordPos[5] = pR.z;
  chordGeo.attributes.position.needsUpdate = true;
  chordGeo.computeBoundingSphere();
  placeCone(chordC1, pL, DIR_L);
  placeCone(chordC2, pR, DIR_R);

  measCircle.scale.set(r * S, 1, r * S);
  measCircle.position.y = v * S;

  measLabel.pos.copy(P(0, v));
  measLabel.div.innerHTML = diam.toFixed(1) + ' m';
}
slider.addEventListener('input', () => { tween = null; updateMeasure(); });
updateMeasure();

/* ── view-mode cross fade ───────────────────────────────────────────────── */
function collect(root, arr) {
  root.traverse(o => {
    if (!o.material) return;
    const ms = Array.isArray(o.material) ? o.material : [o.material];
    ms.forEach(m => { m.transparent = true; arr.push({ m, base: m.opacity }); });
  });
}
const matSolid = [], matContour = [], matRings = [], matLegs = [], matProfile = [];
collect(grpSolid, matSolid);
collect(grpContours, matContour);
collect(grpRings, matRings);
collect(grpLegs, matLegs);
collect(grpProfile, matProfile);

let modeT = 0, modeTarget = 0;       // 0 = full tower, 1 = hyperbola profile
function applyModeFade() {
  const t = modeT, inv = 1 - t;
  for (const a of [matSolid, matContour, matRings, matLegs]) for (const e of a) e.m.opacity = e.base * inv;
  for (const e of matProfile) e.m.opacity = e.base * t;
  grpSolid.visible = inv > 0.004;
  grpContours.visible = inv > 0.004;
  grpRings.visible = inv > 0.004;
  grpLegs.visible = inv > 0.004;
  grpProfile.visible = t > 0.004;
  eqLabel.div.style.opacity = t.toFixed(3);
  ctrLabel.div.style.opacity = t.toFixed(3);
}
applyModeFade();

const btnFull = document.getElementById('modeFull');
const btnProfile = document.getElementById('modeProfile');
function setMode(mode) {
  const profile = (mode === 'Hyperbola profile');
  modeTarget = profile ? 1 : 0;
  btnFull.classList.toggle('active', !profile);
  btnProfile.classList.toggle('active', profile);
  applyCamera(profile);
}
btnFull.addEventListener('click', () => setMode('Full tower'));
btnProfile.addEventListener('click', () => setMode('Hyperbola profile'));

/* ── guided demo steps ──────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The dimensioned elevation',
    narration: 'The cooling tower is shown head-on: 179.6 m tall, 72 m across the flat top, and pinched to a 60 m waist 79.6 m below the top. The dashed lines mark the axis and the waist level.',
    state: { viewMode: 'Full tower', measureHeight: 100 } },
  { title: 'Measuring at the waist',
    narration: 'At 100 m above ground the measuring chord reaches its shortest span, 60 m — the narrowest circle of the tower and the vertex distance of the hyperbola.',
    state: { viewMode: 'Full tower', measureHeight: 100 } },
  { title: 'Above and below the waist',
    narration: 'Move the chord up to the 179.6 m rim and it reads 72 m; drop it toward the ground and it widens again. The width grows symmetrically in both directions away from the waist.',
    state: { viewMode: 'Full tower', measureHeight: 179.6 } },
  { title: 'The fitted hyperbola',
    narration: 'The side of the tower is the branch pair of x²/30² − y²/120² = 1, centred where the axis meets the waist line. The 72 m width at y = 79.6 m is exactly what forces b = 120.',
    state: { viewMode: 'Hyperbola profile', measureHeight: 140 } }
];
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');
let stepIdx = 0;
let tween = null;

function tweenMeasure(target, dur = 750) {
  tween = { from: parseFloat(slider.value), to: target, t0: performance.now(), dur };
}
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + st.title;
  stepNarr.textContent = st.narration;
  setMode(st.state.viewMode);
  tweenMeasure(st.state.measureHeight);
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
goToStep(0);

/* ── local ticker: tweens + mode fade ───────────────────────────────────── */
(function tickLoop() {
  requestAnimationFrame(tickLoop);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    slider.value = String(tween.from + (tween.to - tween.from) * e);
    updateMeasure();
    if (k >= 1) tween = null;
  }
  if (Math.abs(modeT - modeTarget) > 0.002) {
    modeT += (modeTarget - modeT) * 0.12;
    applyModeFade();
  } else if (modeT !== modeTarget) {
    modeT = modeTarget;
    applyModeFade();
  }
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

