// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per element) ───────────────────────────────────
 shell             → LatheGeometry(140 flared-profile samples, 96 seg) MeshPhysicalMaterial #F7C6A5 op .42 DoubleSide depthWrite:false
 meridian contours → LineSegments, 22 azimuths in the NEAR-LEFT quarter only (projects onto left half) #E8845A op .75
 top rim (72 m)    → LineLoop r = 36 m at y = +79.6 m, #E07B43
 shell-bottom rim  → LineLoop r = 68 m at y = −88 m, #E07B43
 waist ring (60 m) → LineLoop r = 30 m at y = 0, #E07B43 faint
 silhouette        → two Lines u = ±rDraw(y), #E07B43
 teal supports     → 20 × BoxGeometry(3 × 12.6 × 5 m) alternating ±18° splay + EdgesGeometry outline #5FA8A3 / #3E8481
 ground line       → Line trimmed to the footprint (±80 m) at y = −100 m, #E07B43
 centre axis       → dashed Line, full height, #E07B43
 waist chord       → dashed Line u = −32..32 at v = 0, #E07B43
 dim 72 m          → Line + 2 cone arrowheads + extension ticks, #333
 dim 60 m          → Line + 2 cones on the dashed waist chord, #333
 dim 79.6 m        → vertical Line + cones + ticks at u = −45 m, #333
 dim 179.6 m       → vertical Line + cones + ticks at u = −110 m, #333
 measuring chord   → Line + 2 cones (#1B6CA8) + LineLoop circle + live HTML readout
 asymptotes        → 2 dashed Lines v = ±4u, #999 (profile mode only)
 true hyperbola    → bold Line pair x = ±30√(1+y²/120²) (profile mode only) + centre dot
──────────────────────────────────────────────────────────────────────────── */

const S = 1 / 40;                       // metres → world units
const A_HYP = 30, B_HYP = 120;          // metres
const Y_TOP = 79.6, Y_GND = -100, Y_BOT = -88;   // waist-relative heights (m)

const rTrue = (y) => A_HYP * Math.sqrt(1 + (y * y) / (B_HYP * B_HYP));
// The printed drawing stylises the base flare much wider than the fitted
// hyperbola; blend a flare in below −15 m so the silhouette reads like the
// source while the 60 m waist and 72 m rim stay exact.
const FLARE_START = -15;
const R_BOT_DRAW = 68;                                   // m, drawn shell-bottom radius
const FLARE_K = R_BOT_DRAW / rTrue(Y_BOT) - 1;
function flare(y) {
  if (y >= FLARE_START) return 1;
  const t = (FLARE_START - y) / (FLARE_START - Y_BOT);
  return 1 + FLARE_K * t * t;
}
const rDraw = (y) => rTrue(y) * flare(y);

// figure-plane point: u = screen-horizontal (metres, +u to the RIGHT), v = height (m)
const P = (u, v) => new THREE.Vector3(0, v * S, -u * S);

const C_FILL = 0xF7C6A5, C_EDGE = 0xE07B43, C_MER = 0xE8845A;
const C_TEAL = 0x5FA8A3, C_TEALD = 0x3E8481, C_DIM = 0x333333, C_MEAS = 0x1B6CA8;

let tween = null;   // declared early: the slider handler clears it

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xeeeeee, 1.0));
const dl = new THREE.DirectionalLight(0xffffff, 0.5);
dl.position.set(3, 4, 2);
scene.add(dl);

/* ── builders ───────────────────────────────────────────────────────────── */
function lineFrom(pts, color, opts = {}) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = opts.dashed
    ? new THREE.LineDashedMaterial({
        color, dashSize: opts.dashSize ?? 0.055, gapSize: opts.gapSize ?? 0.035,
        transparent: true, opacity: opts.opacity ?? 1
      })
    : new THREE.LineBasicMaterial({ color, transparent: true, opacity: opts.opacity ?? 1 });
  const l = new THREE.Line(g, m);
  if (opts.dashed) l.computeLineDistances();
  return l;
}
const ARROW_L = 0.115, ARROW_R = 0.038;
function makeCone(color) {
  return new THREE.Mesh(new THREE.ConeGeometry(ARROW_R, ARROW_L, 14),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
}
const _up = new THREE.Vector3(0, 1, 0);
function placeCone(mesh, tip, dir) {
  mesh.quaternion.setFromUnitVectors(_up, dir);
  mesh.position.copy(tip).addScaledVector(dir, -ARROW_L / 2);
}
function dimArrow(u1, v1, u2, v2, color) {
  const g = new THREE.Group();
  const p1 = P(u1, v1), p2 = P(u2, v2);
  g.add(lineFrom([p1, p2], color));
  const dir = p2.clone().sub(p1).normalize();
  const c2 = makeCone(color), c1 = makeCone(color);
  placeCone(c2, p2, dir); placeCone(c1, p1, dir.clone().negate());
  g.add(c1); g.add(c2);
  return g;
