// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per element) ───────────────────────────────────
 shell             → LatheGeometry(140 profile samples, 96 seg) MeshPhysicalMaterial #F7C6A5 op .42 DoubleSide depthWrite:false
 meridian hatch    → LineSegments, 30 azimuths in the NEAR-LEFT quarter only (screen-left half) #E8845A op .85
 top rim (72 m)    → LineLoop r = 36 m at y = +79.6 m, #E07B43
 shell-bottom rim  → LineLoop r = 62 m at y = −92 m, #E07B43
 waist ring (60 m) → LineLoop r = 30 m at y = 0, #E07B43 faint
 silhouette        → two Lines u = ±rDraw(y), #E07B43
 teal legs         → 18 × BoxGeometry(2.2 × 8.2 × 3.2 m) alternating ±13° splay, tucked inside base rim + EdgesGeometry #5FA8A3 / #3E8481
 ground line       → Line trimmed to the footprint (±70 m) at y = −100 m, #E07B43
 centre axis       → dashed Line, full height, #E07B43
 waist chord       → dashed Line u = −32..32 at v = 0, #E07B43
 dim 72 m          → Line + 2 cone arrowheads + extension ticks, #333
 dim 60 m          → Line + 2 cones on the dashed waist chord + black '60 m' label, #333
 dim 79.6 m        → vertical Line + cones + ticks at u = −45 m, #333
 dim 179.6 m       → vertical Line + cones + ticks at u = −105 m, #333
 measuring chord   → Line + 2 cones (#1B6CA8) + LineLoop circle + live HTML readout offset to the right
 asymptotes        → 2 dashed Lines v = ±4u, #999 (profile mode only)
 true hyperbola    → bold Line pair x = ±30√(1+y²/120²) (profile mode only) + centre dot
──────────────────────────────────────────────────────────────────────────── */

const S = 1 / 40;                       // metres → world units
const A_HYP = 30, B_HYP = 120;          // metres
const Y_TOP = 79.6, Y_GND = -100, Y_BOT = -92;   // waist-relative heights (m)

const rTrue = (y) => A_HYP * Math.sqrt(1 + (y * y) / (B_HYP * B_HYP));
// The printed drawing stylises the base flare wider than the fitted hyperbola;
// blend a modest flare in below −15 m so the silhouette still reads like the
// source while the 60 m waist and the 72 m rim stay exact.
const FLARE_START = -15;
const R_BOT_DRAW = 62;                                   // m, drawn shell-bottom radius
const FLARE_K = R_BOT_DRAW / rTrue(Y_BOT) - 1;
function flare(y) {
  if (y >= FLARE_START) return 1;
  const t = (FLARE_START - y) / (FLARE_START - Y_BOT);
  return 1 + FLARE_K * t * t;
}
const rDraw = (y) => rTrue(y) * flare(y);

// figure-plane point: u = screen-horizontal (metres, +u to the RIGHT), v = height (m)
const P = (u, v) => new THREE.Vector3(0, v * S, -u * S);

const C_FILL = 0xF7C6A5, C_EDGE = 0xE07B43, C_MER = 0xE8845A;
const C_TEAL = 0x5FA8A3, C_TEALD = 0x3E8481, C_DIM = 0x333333, C_MEAS = 0x1B6CA8;

let tween = null;   // declared early: the slider handler clears it

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xeeeeee, 1.0));
const dl = new THREE.DirectionalLight(0xffffff, 0.5);
dl.position.set(3, 4, 2);
scene.add(dl);

/* ── builders ───────────────────────────────────────────────────────────── */
function lineFrom(pts, color, opts = {}) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = opts.dashed
    ? new THREE.LineDashedMaterial({
        color, dashSize: opts.dashSize ?? 0.055, gapSize: opts.gapSize ?? 0.035,
        transparent: true, opacity: opts.opacity ?? 1
      })
    : new THREE.LineBasicMaterial({ color, transparent: true, opacity: opts.opacity ?? 1 });
  const l = new THREE.Line(g, m);
  if (opts.dashed) l.computeLineDistances();
  return l;
}
const ARROW_L = 0.11, ARROW_R = 0.036;
function makeCone(color) {
  return new THREE.Mesh(new THREE.ConeGeometry(ARROW_R, ARROW_L, 14),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
}
const _up = new THREE.Vector3(0, 1, 0);
function placeCone(mesh, tip, dir) {
  mesh.quaternion.setFromUnitVectors(_up, dir);
  mesh.position.copy(tip).addScaledVector(dir, -ARROW_L / 2);
}
function dimArrow(u1, v1, u2, v2, color) {
  const g = new THREE.Group();
  const p1 = P(u1, v1), p2 = P(u2, v2);
  g.add(lineFrom([p1, p2], color));
  const dir = p2.clone().sub(p1).normalize();
  const c2 = makeCone(color), c1 = makeCone(color);
  placeCone(c2, p2, dir); placeCone(c1, p1, dir.clone().negate());
  g.add(c1); g.add(c2);
  return g;
}
const tick = (u1, v1, u2, v2, c) => lineFrom([P(u1, v1), P(u2, v2)], c);
function circleLoop(radiusW, yW, color, opacity = 1, segs = 96) {
  const pts = [];
  for (let i = 0; i <= segs; i++) {
    const a = i / segs * Math.PI * 2;
    pts.push(new THREE.Vector3(Math.cos(a) * radiusW, yW, Math.sin(a) * radiusW));
  }
  return lineFrom(pts, color, { opacity });
}

/* ── profile samples (drawn shell: Y_BOT → Y_TOP) ───────────────────────── */
const NP = 140;
const profile2 = [], profileY = [];
for (let i = 0; i < NP; i++) {
  const y = Y_BOT + (Y_TOP - Y_BOT) * i / (NP - 1);
  profileY.push(y);
  profile2.push(new THREE.Vector2(rDraw(y) * S, y * S));
}

/* ── 1. shell (lathe) ───────────────────────────────────────────────────── */
const grpSolid = new THREE.Group(); scene.add(grpSolid);
const shellMat = new THREE.MeshPhysicalMaterial({
  color: C_FILL, transparent: true, opacity: 0.42, side: THREE.DoubleSide,
  depthWrite: false, roughness: 0.8, metalness: 0.0, clearcoat: 0.15
});
const shell = new THREE.Mesh(new THREE.LatheGeometry(profile2, 96), shellMat);
grpSolid.add(shell);

/* ── 2. meridian hatch — NEAR-LEFT quarter only → screen-left half ──────── */
const grpContours = new THREE.Group(); scene.add(grpContours);
{
  const segPts = [];
  const NM = 30, NS = 90;
  for (let k = 0; k < NM; k++) {
    // camera sits on +X: near side x>0, screen-left is +z → phi in (0°,90°]
    const t = Math.pow((k + 1) / NM, 0.85);          // mild crowding at the left edge
    const phi = Math.asin(Math.min(1, t));
    const cx = Math.cos(phi), cz = Math.sin(phi);
    let prev = null;
    for (let i = 0; i < NS; i++) {
      const y = Y_BOT + (Y_TOP - Y_BOT) * i / (NS - 1);
      const r = rDraw(y) * S;
      const p = new THREE.Vector3(cx * r, y * S, cz * r);
      if (prev) segPts.push(prev, p);
      prev = p;
    }
  }
  grpContours.add(new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(segPts),
    new THREE.LineBasicMaterial({ color: C_MER, transparent: true, opacity: 0.85 })));
}

/* ── 3. rings + measurement circle ──────────────────────────────────────── */
const grpRings = new THREE.Group(); scene.add(grpRings);
grpRings.add(circleLoop(rDraw(Y_TOP) * S, Y_TOP * S, C_EDGE, 1));       // 72 m top rim
grpRings.add(circleLoop(R_BOT_DRAW * S, Y_BOT * S, C_EDGE, 0.95));      // open base rim
grpRings.add(circleLoop(A_HYP * S, 0, C_EDGE, 0.5));                    // 60 m waist ring
const measCircle = circleLoop(1, 0, C_MEAS, 0.7);
grpRings.add(measCircle);

/* ── 4. short teal splayed legs, tucked inside the base footprint ───────── */
const grpLegs = new THREE.Group(); scene.add(grpLegs);
{
  const TILT = THREE.MathUtils.degToRad(13);
  const GAP = Y_BOT - Y_GND;                                   // 8 m of open base
  const LEG_LEN = GAP / Math.cos(TILT);                        // ≈ 8.2 m
  const legGeo = new THREE.BoxGeometry(2.2 * S, LEG_LEN * S, 3.2 * S);
  const legMat = new THREE.MeshPhysicalMaterial({ color: C_TEAL, transparent: true, roughness: 0.75 });
  const edgeGeo = new THREE.EdgesGeometry(legGeo);
  const edgeMat = new THREE.LineBasicMaterial({ color: C_TEALD, transparent: true });
  const NL = 18;
  for (let i = 0; i < NL; i++) {
    const a = i / NL * Math.PI * 2;
    const pivot = new THREE.Group();
    pivot.rotation.y = -a;                      // local +X radially outward
    const sign = (i % 2 === 0) ? 1 : -1;        // alternating splay → V pattern
    const leg = new THREE.Mesh(legGeo, legMat);
    leg.position.set((R_BOT_DRAW - 2.5) * S, (Y_GND + Y_BOT) / 2 * S, 0);
    leg.rotation.z = sign * TILT;
    const outline = new THREE.LineSegments(edgeGeo, edgeMat);
    outline.position.copy(leg.position); outline.rotation.z = leg.rotation.z;
    pivot.add(leg, outline);
    grpLegs.add(pivot);
  }
}

/* ── 5. flat (always-visible) figure elements ───────────────────────────── */
const grpFlat = new THREE.Group(); scene.add(grpFlat);

// drawn silhouette
const silL = [], silR = [];
for (const y of profileY) { silL.push(P(-rDraw(y), y)); silR.push(P(rDraw(y), y)); }
const silLine1 = lineFrom(silL, C_EDGE), silLine2 = lineFrom(silR, C_EDGE);
grpFlat.add(silLine1, silLine2);

// ground line — trimmed to the tower footprint
const GL = R_BOT_DRAW + 8;
grpFlat.add(lineFrom([P(-GL, Y_GND), P(GL, Y_GND)], C_EDGE, { opacity: 0.9 }));

// dashed axis of revolution + dashed waist chord
grpFlat.add(lineFrom([P(0, Y_GND), P(0, Y_TOP + 3)], C_EDGE, { dashed: true, opacity: 0.95 }));
grpFlat.add(lineFrom([P(-32, 0), P(32, 0)], C_EDGE, { dashed: true, opacity: 0.95 }));

// dimensions
grpFlat.add(dimArrow(-36, Y_TOP + 16, 36, Y_TOP + 16, C_DIM));
grpFlat.add(tick(-36, Y_TOP + 2, -36, Y_TOP + 21, C_DIM));
grpFlat.add(tick(36, Y_TOP + 2, 36, Y_TOP + 21, C_DIM));
grpFlat.add(dimArrow(-30, 0, 30, 0, C_DIM));
grpFlat.add(dimArrow(-45, Y_TOP, -45, 0, C_DIM));
grpFlat.add(tick(-52, Y_TOP, -38, Y_TOP, C_DIM));
grpFlat.add(tick(-52, 0, -38, 0, C_DIM));
grpFlat.add(dimArrow(-105, Y_TOP, -105, Y_GND, C_DIM));
grpFlat.add(tick(-112, Y_TOP, -98, Y_TOP, C_DIM));
grpFlat.add(tick(-112, Y_GND, -98, Y_GND, C_DIM));

// measuring chord (interactive)
const chordPos = new Float32Array(6);
const chordGeo = new THREE.BufferGeometry();
chordGeo.setAttribute('position', new THREE.BufferAttribute(chordPos, 3));
const chordLine = new THREE.Line(chordGeo, new THREE.LineBasicMaterial({ color: C_MEAS }));
const chordC1 = makeCone(C_MEAS), chordC2 = makeCone(C_MEAS);
grpFlat.add(chordLine, chordC1, chordC2);

/* ── 6. hyperbola-profile extras ────────────────────────────────────────── */
const grpProfile = new THREE.Group(); grpProfile.visible = false; scene.add(grpProfile);
{
  const hypL = [], hypR = [];
  for (let i = 0; i < NP; i++) {
    const y = Y_GND + (Y_TOP - Y_GND) * i / (NP - 1);
    hypL.push(P(-rTrue(y), y)); hypR.push(P(rTrue(y), y));
  }
  for (const off of [-0.007, 0, 0.007]) {
    for (const pts of [hypL, hypR]) {
      grpProfile.add(lineFrom(pts.map(p => new THREE.Vector3(p.x + off, p.y, p.z)), C_EDGE));
    }
  }
  const U = 26;
  grpProfile.add(lineFrom([P(-U, 4 * U), P(U, -4 * U)], 0x999999, { dashed: true, dashSize: 0.05, gapSize: 0.045 }));
  grpProfile.add(lineFrom([P(-U, -4 * U), P(U, 4 * U)], 0x999999, { dashed: true, dashSize: 0.05, gapSize: 0.045 }));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.035, 16, 12),
    new THREE.MeshBasicMaterial({ color: C_EDGE, transparent: true }));
  dot.position.copy(P(0, 0));
  grpProfile.add(dot);
}

/* ── camera (after all geometry) — head-on elevation, exactly as printed ── */
function applyCamera() {
  setCameraView({
    projection: 'perspective',
    azimuthDeg: 0,
    elevationDeg: 0,
    rollDeg: 0,
    heightFraction: 0.8
  });
}
applyCamera();
document.getElementById('btnReset').style.display = '';

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('72 m', P(0, Y_TOP + 16), { color: '#333', fontSize: '14px', offset: [0, -13], background: '#fff' });
addLabel('60 m', P(0, 0), { color: '#333', fontSize: '14px', offset: [0, -13], background: '#fff' });
addLabel('79.6 m', P(-45, 40), { color: '#333', fontSize: '14px', offset: [-38, 0] });
addLabel('179.6 m', P(-105, -10), { color: '#333', fontSize: '14px', offset: [-44, 0] });
const measLabel = addLabel('60.0 m', P(0, 0), { color: '#1B6CA8', fontSize: '13px', bold: true, offset: [50, -10], background: '#fff' });
const eqLabel = addLabel('x²/30² &minus; y²/120² = 1', P(70, 56), { color: '#E07B43', fontSize: '14px', bold: true });
eqLabel.div.style.opacity = '0';
const ctrLabel = addLabel('centre', P(0, 0), { color: '#E07B43', fontSize: '11px', offset: [-34, 14] });
ctrLabel.div.style.opacity = '0';
const asyLabel = addLabel('asymptotes y = &plusmn;4x', P(30, -96), { color: '#888', fontSize: '11px', offset: [36, 0] });
asyLabel.div.style.opacity = '0';

/* ── hover / click explanations ─────────────────────────────────────────── */
registerInteractive(shell, {
  title: 'Hyperboloid shell',
  tooltip: 'The shell is a surface of revolution',
  body: 'Rotating the hyperbola x²/30² − y²/120² = 1 about the vertical axis gives the tower. ' +
        'At height y above the waist the radius is r(y) = 30·√(1 + y²/120²), so r(0) = 30 m (60 m waist) ' +
        'and r(79.6) = 36 m (72 m top rim). As in the textbook drawing, the base flare is slightly exaggerated.'
});
registerInteractive(grpLegs, {
  title: 'Base supports',
  tooltip: 'Short splayed legs under the open base',
  body: 'A ring of short, alternately splayed columns lifts the shell about 8 m off the ground so air is drawn ' +
        'in all round the base. They sit just inside the base rim, so they do not widen the silhouette.'
});

/* ── measurement chord ──────────────────────────────────────────────────── */
const slider = document.getElementById('measureHeight');
const mhOut = document.getElementById('mhOut');
const diamOut = document.getElementById('diamOut');
const DIR_R = new THREE.Vector3(0, 0, -1), DIR_L = new THREE.Vector3(0, 0, 1);
let modeT = 0, modeTarget = 0;   // 0 = full tower, 1 = hyperbola profile

function updateMeasure() {
  const h = parseFloat(slider.value);
  const v = h - 100;
  const vShell = Math.max(v, Y_BOT);                       // shell is open below 8 m
  const r = rDraw(vShell) * (1 - modeT) + rTrue(v) * modeT; // morphs with the view toggle
  const diam = 2 * r;
  mhOut.textContent = h.toFixed(1);
  diamOut.textContent = 'diameter = ' + diam.toFixed(1) + ' m' + (v < Y_BOT ? '  (base rim)' : '');

  const vDraw = modeT > 0.5 ? v : vShell;
  const pL = P(-r, vDraw), pR = P(r, vDraw);
  chordPos[0] = pL.x; chordPos[1] = pL.y; chordPos[2] = pL.z;
  chordPos[3] = pR.x; chordPos[4] = pR.y; chordPos[5] = pR.z;
  chordGeo.attributes.position.needsUpdate = true;
  chordGeo.computeBoundingSphere();
  placeCone(chordC1, pL, DIR_L);
  placeCone(chordC2, pR, DIR_R);

  measCircle.scale.set(r * S, 1, r * S);
  measCircle.position.y = vDraw * S;

  // live readout parked off the right end of the chord, so the printed black
  // '60 m' on the waist chord is never duplicated or covered
  measLabel.pos.copy(P(r, vDraw));
  measLabel.div.innerHTML = diam.toFixed(1) + ' m';
}
slider.addEventListener('input', () => { tween = null; updateMeasure(); });
updateMeasure();

/* ── view-mode cross fade ───────────────────────────────────────────────── */
function collect(root, arr) {
  root.traverse(o => {
    if (!o.material) return;
    const ms = Array.isArray(o.material) ? o.material : [o.material];
    ms.forEach(m => { m.transparent = true; arr.push({ m, base: m.opacity }); });
  });
}
const matSolid = [], matContour = [], matRings = [], matLegs = [], matProfile = [], matSil = [];
collect(grpSolid, matSolid);
collect(grpContours, matContour);
collect(grpRings, matRings);
collect(grpLegs, matLegs);
collect(grpProfile, matProfile);
collect(silLine1, matSil); collect(silLine2, matSil);

function applyModeFade() {
  const t = modeT, inv = 1 - t;
  for (const a of [matSolid, matContour, matRings, matLegs, matSil]) for (const e of a) e.m.opacity = e.base * inv;
  for (const e of matProfile) e.m.opacity = e.base * t;
  grpSolid.visible = inv > 0.004;
  grpContours.visible = inv > 0.004;
  grpRings.visible = inv > 0.004;
  grpLegs.visible = inv > 0.004;
  silLine1.visible = silLine2.visible = inv > 0.004;
  grpProfile.visible = t > 0.004;
  eqLabel.div.style.opacity = t.toFixed(3);
  ctrLabel.div.style.opacity = t.toFixed(3);
  asyLabel.div.style.opacity = t.toFixed(3);
}
applyModeFade();

const btnFull = document.getElementById('modeFull');
const btnProfile = document.getElementById('modeProfile');
function setMode(mode) {
  const profile = (mode === 'Hyperbola profile');
  modeTarget = profile ? 1 : 0;
  btnFull.classList.toggle('active', !profile);
  btnProfile.classList.toggle('active', profile);
  applyCamera();     // snap back to the head-on elevation for either mode
}
btnFull.addEventListener('click', () => setMode('Full tower'));
btnProfile.addEventListener('click', () => setMode('Hyperbola profile'));

/* ── guided demo steps ──────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The dimensioned elevation',
    narration: 'The cooling tower is shown head-on: 179.6 m tall, 72 m across the flat top, and pinched to a 60 m waist 79.6 m below the top. The dashed lines mark the axis of revolution and the waist level; a ring of short teal legs holds the shell 8 m clear of the ground.',
    state: { viewMode: 'Full tower', measureHeight: 100 } },
  { title: 'Measuring at the waist',
    narration: 'At 100 m above ground the measuring chord reaches its shortest span, 60 m — the narrowest circle of the tower and the vertex distance 2a of the hyperbola.',
    state: { viewMode: 'Full tower', measureHeight: 100 } },
  { title: 'Above and below the waist',
    narration: 'Move the chord up to the 179.6 m rim and it reads 72 m; drop it toward the ground and it widens again. The width grows in both directions away from the waist.',
    state: { viewMode: 'Full tower', measureHeight: 179.6 } },
  { title: 'The fitted hyperbola',
    narration: 'The side of the tower is the branch pair of x²/30² − y²/120² = 1, centred where the axis meets the waist line. The 72 m width at y = 79.6 m is exactly what forces b = 120. (The drawing flares the base wider for effect; the fitted curve gives about 78 m at ground level.)',
    state: { viewMode: 'Hyperbola profile', measureHeight: 140 } }
];
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');
let stepIdx = 0;

function tweenMeasure(target, dur = 750) {
  tween = { from: parseFloat(slider.value), to: target, t0: performance.now(), dur };
}
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + st.title;
  stepNarr.textContent = st.narration;
  setMode(st.state.viewMode);
  tweenMeasure(st.state.measureHeight);
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
goToStep(0);

/* ── local ticker: tweens + mode fade ───────────────────────────────────── */
(function tickLoop() {
  requestAnimationFrame(tickLoop);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    slider.value = String(tween.from + (tween.to - tween.from) * e);
    updateMeasure();
    if (k >= 1) tween = null;
  }
  if (Math.abs(modeT - modeTarget) > 0.002) {
    modeT += (modeTarget - modeT) * 0.12;
    applyModeFade();
    updateMeasure();
  } else if (modeT !== modeTarget) {
    modeT = modeTarget;
    applyModeFade();
    updateMeasure();
  }
})();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.
